    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return {"error": "아이디와 비밀번호를 JSON으로 보내 주세요."}, 400

    username = data.get("username")
    password = data.get("password")

    if not isinstance(username, str) or not isinstance(password, str):
        return {"error": "아이디와 비밀번호를 문자열로 보내 주세요."}, 400

    username_trimmed = username.strip()
    password_trimmed = password.strip()

    if not username_trimmed or not password_trimmed:
        return {"error": "아이디와 비밀번호를 모두 입력해 주세요."}, 400

    user = find_user_by_username(username_trimmed)
    if user is None or not check_password_hash(user["password_hash"], password):
        return {"error": "아이디 또는 비밀번호가 올바르지 않습니다."}, 401

    # 세션에 로그인 정보 저장 (심화 4: 세션 유지 지원)
    session["user_id"] = user["id"]
    session["username"] = user["username"]

    return {
        "message": "로그인 성공",
        "user": {"id": user["id"], "username": user["username"]},
    }, 200

@auth_bp.post("/logout")
def logout():
    session.clear()
    return {"message": "로그아웃되었습니다."}, 200

